/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect, useCallback } from 'react'
import {
  Table,
  Row,
  Col,
  Spin,
  Typography,
  Button,
  Icon,
  Alert,
  message
} from 'antd'
import PropTypes from 'prop-types'
import { format } from 'date-fns'
import LayoutContent from '../../../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../../../components/utility/layoutWrapper'
import { useDownloadFileUploads, useFileDetail, useCancelFile, useFileRows, useResetState } from '../../state/hooks'
import { downloadDataFromUrl } from '../../../../../helpers/utility'
import { RowWithMargin } from '../../CommonComponents'
import { ColTextAlignRight } from '../../CommonComponents/index.style'
import { StyledAntdButton } from '../../../../../components/uielements/customButton'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useHistory, useParams } from 'react-router'
import { commonColumns } from './utility'
import PermissionCheckerV2 from '../../../../../components/permissionCheckerV2'

const { Title, Text } = Typography

const FileUploadDetail = ({ fileUploadDetailColumns = () => [], cancelPermissionName = '', downloadPermissionName = '', cancelUrl }) => {
  const history = useHistory()
  const params = useParams()
  const [listData, setListData] = useState([])
  const [listMetaData, setListMetaData] = useState({})
  const { fileDetailData, getFileDetail } = useFileDetail()
  const { fileRowsData, getFileRows } = useFileRows()
  const { cancelFileData, cancelFileRequest } = useCancelFile()
  const [{ FILE_DETAIL_LOADER }] = useLoaderContextValue()
  const [{ FILE_DETAIL_ERROR, DOWNLOAD_FILE_UPLOADS_ERROR, CANCEL_FILE_ERROR, FILE_ROWS_ERROR, fileDetailStatus, fileRowsStatus, cancelFileStatus, downloadFileUploadsStatus }] = useErrorContextValue()
  const [{ downloadFileUploadsData }, downloadFileUploads] = useDownloadFileUploads()
  const { resetState } = useResetState()
  const { resetError } = useResetError()

  useEffect(() => {
    return () => {
      resetState([
        'fileDetailData',
        'fileDetailStatus',
        'fileRowsData',
        'fileRowsStatus',
        'downloadFileUploadsData',
        'downloadFileUploadsStatus',
        'cancelFileStatus',
        'cancelFileData'
      ])
      resetError([
        'FILE_DETAIL_ERROR',
        'DOWNLOAD_FILE_UPLOADS_ERROR',
        'CANCEL_FILE_ERROR',
        'FILE_ROWS_ERROR'
      ])
    }
  }, [])

  useEffect(() => {
    if (FILE_DETAIL_ERROR === undefined) {
      getFileDetail({ file_id: params.fileId })
    }
  }, [fileDetailData, fileDetailStatus])

  useEffect(() => {
    if (fileRowsData && fileRowsData.data && fileRowsStatus === 'success') {
      setListData(fileRowsData.data)
      setListMetaData(fileRowsData.meta_data)
    } else if (!fileRowsData && FILE_ROWS_ERROR === undefined) {
      getFileRows({ file_id: parseInt(params.fileId) })
    }
  }, [fileRowsData, fileRowsStatus])

  const handleTableChange = (tableParams) => {
    const query = {
      file_id: params.fileId,
      page: tableParams.current,
      per_page: tableParams.pageSize
    }
    getFileRows(query)
  }

  const goBack = useCallback(() => {
    history.goBack()
  }, [history])

  const handleCancelFile = () => {
    resetError(['CANCEL_FILE_ERROR'])
    cancelFileRequest({ file_id: parseInt(params.fileId), url: cancelUrl })
  }

  const handleDownloadClick = (status) => {
    resetError(['DOWNLOAD_FILE_UPLOADS_ERROR'])
    downloadFileUploads({ file_id: parseInt(params.fileId), status })
  }

  useEffect(() => {
    if (!CANCEL_FILE_ERROR && cancelFileData && cancelFileData.message === 'Success') {
      message.success('File cancellation successfull')
      getFileDetail({ file_id: params.fileId })
      resetState(['cancelFileData', 'cancelFileStatus'])
    }
    if (downloadFileUploadsData && downloadFileUploadsData.url && !DOWNLOAD_FILE_UPLOADS_ERROR) {
      downloadDataFromUrl(downloadFileUploadsData.url)
      resetState(['downloadFileUploadsData', 'downloadFileUploadsStatus'])
    }
  }, [cancelFileData, cancelFileStatus, downloadFileUploadsData])

  return (
    <LayoutContentWrapper>
      <Button onClick={goBack}><Icon type='arrow-left' /> Back</Button>
      <LayoutContent>
        {(FILE_DETAIL_ERROR) && <Alert type='error' message={fileDetailStatus} banner />}
        {(CANCEL_FILE_ERROR) && <Alert type='error' message={cancelFileStatus} banner />}
        {(FILE_ROWS_ERROR) && <Alert type='error' message={fileRowsStatus} banner />}
        {(DOWNLOAD_FILE_UPLOADS_ERROR) && <Alert type='error' message={downloadFileUploadsStatus} banner />}
        <RowWithMargin>
          <Title level={4}>File Detail</Title>
          <Col span={12}>
            <Row>
              <Col span={4}><Text strong>Name</Text></Col>
              <Col span={12}>{fileDetailData?.name}</Col>
            </Row>
            <Row>
              <Col span={4}><Text strong>Status</Text></Col>
              <Col span={12}>{fileDetailData?.status}</Col>
            </Row>
            <Row>
              <Col span={4}><Text strong>Uploaded at</Text></Col>
              <Col span={12}>{fileDetailData?.uploaded_at && format(fileDetailData.uploaded_at, 'DD-MM-YYYY')}</Col>
            </Row>
            <Row>
              <Col span={4}><Text strong>Errors</Text></Col>
              <Col span={12}>{fileDetailData?.errors}</Col>
            </Row>
          </Col>
          <Col span={12}>
            <PermissionCheckerV2 requiredPermission={downloadPermissionName}>
              <Row>
                <ColTextAlignRight>
                  <Button
                    type='primary'
                    shape='round'
                    icon='download' size='small'
                    onClick={() => handleDownloadClick()}
                  >
                    Download Original
                  </Button>
                </ColTextAlignRight>
              </Row>
              <Row>
                <ColTextAlignRight>
                  <StyledAntdButton
                    type='customSuccess'
                    shape='round'
                    icon='download'
                    size='small'
                    onClick={() => handleDownloadClick('SUCCESS')}
                  >
                    Download Success
                  </StyledAntdButton>
                </ColTextAlignRight>
              </Row>
              <Row>
                <ColTextAlignRight>
                  <StyledAntdButton
                    type='customDanger'
                    shape='round'
                    icon='download'
                    size='small'
                    onClick={() => handleDownloadClick('FAILED')}
                  >
                    Download failed
                  </StyledAntdButton>
                </ColTextAlignRight>
              </Row>
            </PermissionCheckerV2>
            <PermissionCheckerV2 requiredPermission={cancelPermissionName}>
              <Row>
                <ColTextAlignRight>
                  {
                    fileDetailData && ['UPLOADED', 'INPROCESS'].includes(fileDetailData?.status) && (
                      <StyledAntdButton
                        type='customPrimary'
                        shape='round'
                        icon='close'
                        size='small'
                        onClick={handleCancelFile}
                      >
                        Cancel
                      </StyledAntdButton>
                    )
                  }
                </ColTextAlignRight>
              </Row>
            </PermissionCheckerV2>
          </Col>
        </RowWithMargin>
        <RowWithMargin />
        <Spin spinning={FILE_DETAIL_LOADER}>
          <Table
            columns={[...fileUploadDetailColumns(), ...commonColumns()]}
            dataSource={listData}
            onChange={handleTableChange}
            bordered
            pagination={{
              pageSize: listMetaData.page_size,
              total: listMetaData.total_records,
              current: listMetaData.page
            }}
          />
        </Spin>
      </LayoutContent>
    </LayoutContentWrapper>
  )
}

export default FileUploadDetail

FileUploadDetail.proptTypes = {
  fileUploadDetailColumns: PropTypes.func
}
