import { Button } from 'antd'
import styled from 'styled-components'
import themes from '../../settings/themes'

const types = {
  customSuccess: {
    color: themes.themeEb.white,
    backgroundColor: themes.themeEb.green
  },
  customDanger: {
    color: themes.themeEb.white,
    backgroundColor: themes.themeEb.red
  },
  customPrimary: {
    color: themes.themeEb.white,
    backgroundColor: themes.themeEb.lightBlue
  }
}

export const StyledAntdButton = styled(Button)`
    ${({ type }) => type && types[type]
    ? `
    color: ${types[type]['color']}!important;
    background-color: ${types[type]['backgroundColor']}!important;
    `
    : ''}
`
